#include <stdio.h>

#define MAXN 100005

static int a[MAXN];
static int nxt[MAXN]; /* nxt[i] = menor j >= i com a[j]==1, ou n+1 se nao existir */

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    for (int i = 1; i <= n; i++) {
        if (scanf("%d", &a[i]) != 1) return 0;
    }

    nxt[n + 1] = n + 1;
    for (int i = n; i >= 1; i--) {
        nxt[i] = (a[i] == 1) ? i : nxt[i + 1];
    }

    long long ans = 0;
    int prev = 0; /* indice do destaque anterior (0 = nenhum) */
    for (int i = 1; i <= n; i++) {
        if (a[i] == 1) {
            /* l em (prev, i], r em [i, nxt[i+1]) */
            ans += (long long)(i - prev) * (long long)(nxt[i + 1] - i);
            prev = i;
        }
    }

    printf("%lld\n", ans);
    return 0;
}
